-- Isolated test fixture. Current Rust column types. Never use as production baseline or migration.
CREATE TABLE public."auth" (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "id_user" integer,
 "access_token" text,
 "access_token_expiry" bigint,
 "refresh_token" text,
 "refresh_token_hash" text,
 "refresh_token_expiry" bigint,
 "type" integer,
 "provider" varchar NOT NULL DEFAULT '',
 "date_created" timestamptz NOT NULL DEFAULT now(),
 "date_updated" timestamptz
);
CREATE TABLE public."level" (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "hash" text NOT NULL DEFAULT '',
 "xx_hash" text NOT NULL DEFAULT '',
 "simhash" bigint,
 "adventure" boolean NOT NULL DEFAULT false,
 "has_records" boolean NOT NULL DEFAULT false,
 "record_count" bigint NOT NULL DEFAULT 0,
 "publicly_visible" boolean NOT NULL DEFAULT true,
 "date_created" timestamptz NOT NULL DEFAULT now(),
 "date_updated" timestamptz
);
CREATE TABLE public."level_item" (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "id_level" integer NOT NULL DEFAULT 0,
 "workshop_id" bigint NOT NULL DEFAULT 0,
 "author_id" bigint NOT NULL DEFAULT 0,
 "name" text NOT NULL DEFAULT '',
 "image_url" text NOT NULL DEFAULT '',
 "file_author" text NOT NULL DEFAULT '',
 "file_uid" text NOT NULL DEFAULT '',
 "validation_time_author" real NOT NULL DEFAULT 0,
 "validation_time_gold" real NOT NULL DEFAULT 0,
 "validation_time_silver" real NOT NULL DEFAULT 0,
 "validation_time_bronze" real NOT NULL DEFAULT 0,
 "deleted" boolean NOT NULL DEFAULT false,
 "publicly_visible" boolean NOT NULL DEFAULT true,
 "rtm_sample_key" double precision NOT NULL DEFAULT 0,
 "created_at" timestamptz NOT NULL DEFAULT now(),
 "updated_at" timestamptz NOT NULL DEFAULT now(),
 "date_created" timestamptz NOT NULL DEFAULT now(),
 "date_updated" timestamptz
);
CREATE TABLE public."level_metadata" (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "id_level" integer NOT NULL DEFAULT 0,
 "amount_checkpoints" integer NOT NULL DEFAULT 0,
 "amount_finishes" integer NOT NULL DEFAULT 0,
 "amount_blocks" integer NOT NULL DEFAULT 0,
 "type_ground" integer NOT NULL DEFAULT 0,
 "type_skybox" integer NOT NULL DEFAULT 0,
 "environment" jsonb,
 "format" integer NOT NULL DEFAULT 0,
 "blocks" jsonb NOT NULL DEFAULT '{}',
 "publicly_visible" boolean NOT NULL DEFAULT true,
 "date_created" timestamptz NOT NULL DEFAULT now(),
 "date_updated" timestamptz
);
