 "date_updated" timestamptz
);
CREATE TABLE public."level_request" (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "workshop_id" bigint NOT NULL DEFAULT 0,
 "uid" text,
