CREATE TABLE public."track_tournament" (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "type" integer NOT NULL DEFAULT 0,
 "slug" text NOT NULL DEFAULT '',
 "id_level" integer NOT NULL DEFAULT 0,
