 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "steam_name" varchar,
 "banned" boolean NOT NULL DEFAULT false,
 "steam_id" bigint,
 "discord_id" bigint,
 "date_created" timestamptz NOT NULL DEFAULT now(),
 "date_updated" timestamptz
);
CREATE TABLE public."version" (
 "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "minimum" text,
 "latest" text,
