 "date_updated" timestamptz,
 "id_user" integer NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX ON public."user" (steam_id);
CREATE UNIQUE INDEX ON public."level" (xx_hash);
CREATE UNIQUE INDEX ON public."record_media" (id_record);
CREATE UNIQUE INDEX ON public."record_statistic" (id_record);
CREATE UNIQUE INDEX ON public."personal_best_global" (id_user,id_level);
CREATE UNIQUE INDEX ON public."world_record_global" (id_level);
CREATE UNIQUE INDEX ON public."track_tournament_result" (id_tournament,id_user);
CREATE UNIQUE INDEX ON public."workshop_item" (workshop_id);
CREATE UNIQUE INDEX ON public."level_request" (workshop_id);

CREATE UNIQUE INDEX ON public.level_points(id_level);
CREATE TABLE public.user_point_contribution(id_user integer NOT NULL,id_level integer NOT NULL,id_record integer NOT NULL,contribution_rank integer NOT NULL,level_position integer NOT NULL,level_points integer NOT NULL,level_decayed_points real NOT NULL,player_decayed_points real NOT NULL,date_calculated timestamptz NOT NULL,PRIMARY KEY(id_user,id_level));
